<?php $editing=(bool)$car; ?><section class="page container narrow"><div class="page-title"><div><span class="eyebrow">Iklan berkualitas lebih cepat laku</span><h1><?= $editing?'Edit Iklan':'Jual Mobilmu' ?></h1><p>Lengkapi informasi kendaraan secara jujur dan jelas.</p></div></div><form class="form-card" method="post" enctype="multipart/form-data"><?= csrf_field() ?><div class="form-section"><h2>Informasi utama</h2><div class="form-grid"><label class="full">Judul iklan<input name="title" required minlength="8" value="<?= e($car['title']??'') ?>" placeholder="Contoh: Toyota Avanza G 2021 Kondisi Istimewa"></label><label>Merek<input name="brand" required value="<?= e($car['brand']??'') ?>"></label><label>Model<input name="model" required value="<?= e($car['model']??'') ?>"></label><label>Tahun<input type="number" name="year" min="1950" max="<?= date('Y')+1 ?>" required value="<?= e((string)($car['year']??'')) ?>"></label><label>Harga (Rp)<input type="number" name="price" min="1" required value="<?= e((string)($car['price']??'')) ?>"></label><label>Jarak tempuh (km)<input type="number" name="mileage" min="0" required value="<?= e((string)($car['mileage']??'')) ?>"></label><label>Transmisi<select name="transmission" required><option>Manual</option><option <?= ($car['transmission']??'')==='Otomatis'?'selected':'' ?>>Otomatis</option></select></label><label>Bahan bakar<select name="fuel" required><?php foreach(['Bensin','Diesel','Hybrid','Listrik'] as $v): ?><option <?= ($car['fuel']??'')===$v?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label><label>Warna<input name="color" required value="<?= e($car['color']??'') ?>"></label><label>Kota<input name="city" required value="<?= e($car['city']??'') ?>"></label><?php if($editing): ?><label>Status<select name="status"><option value="active">Aktif</option><option value="sold" <?= $car['status']==='sold'?'selected':'' ?>>Terjual</option></select></label><?php endif; ?><label class="full">Deskripsi<textarea 